//! Generative UI: the backend's tools answer with screen documents (a title, cards, and on a card
//! a big number, a chart, a bar, a photo, lines and buttons). This module draws any of them, so
//! what the screen shows is generated by what was asked: the weather comes with its chart, a photo
//! with its suggested edits, the dashboard with today's numbers. Buttons say words back to the
//! agent, so pressing one is the same as asking.
use crate::State;
use crate::icons;
use crate::theme::*;
use rune::tok::TextStyle;
use rune::{Color, El, Icon, Pixels, col, el, icon, row};
use serde_json::Value;
use std::collections::HashMap;

/// The icon and colour for a kind of answer.
pub fn kind_mark(kind: &str) -> (&'static Icon, Color) {
    match kind {
        "weather" => (&icons::SPARK, ACCENT2),
        "air" => (&icons::SIGNAL, GOOD),
        "money" => (&icons::BOLT, WARN),
        "photo" => (&icons::CAMERA, ACCENT),
        "dashboard" => (&icons::APPS, ACCENT),
        _ => (&icons::SPARK, ACCENT),
    }
}

fn tone_colour(tone: &str) -> Color {
    match tone {
        "ok" => GOOD,
        "warn" => WARN,
        "info" => ACCENT2,
        _ => ACCENT,
    }
}

/// Decode the photos a document shows, once each, for the screen.
pub fn load_images(doc: &Value, cache: &mut HashMap<String, Pixels>) {
    for c in doc["cards"].as_array().into_iter().flatten() {
        let Some(path) = c["image"].as_str().filter(|p| !p.is_empty()) else {
            continue;
        };
        if cache.contains_key(path) {
            continue;
        }
        if let Ok(img) = image::open(path) {
            let small = img.thumbnail(720, 720).to_rgba8();
            let px = Pixels::new();
            px.set(small.width(), small.height(), small.into_raw());
            cache.insert(path.to_string(), px);
        }
    }
}

/// A chart: bars, or dots for a line. Labels underneath; the highest value on top.
fn chart(ch: &Value, c: Color, key: &str) -> El {
    let values: Vec<f64> = ch["values"]
        .as_array()
        .into_iter()
        .flatten()
        .filter_map(Value::as_f64)
        .collect();
    let labels: Vec<String> = ch["labels"]
        .as_array()
        .into_iter()
        .flatten()
        .map(str_of)
        .collect();
    let unit = str_of(&ch["unit"]);
    let line = ch["kind"].as_str() == Some("line");
    let (lo, hi) = values
        .iter()
        .fold((f64::MAX, f64::MIN), |(a, b), v| (a.min(*v), b.max(*v)));
    let floor = if line {
        lo - (hi - lo).max(1.0) * 0.4
    } else {
        0.0
    };
    let span = (hi - floor).max(1e-9);
    let mut bars = row().w_full().h(110.0).gap(8.0).items_end();
    for (i, v) in values.iter().enumerate() {
        let h = (((v - floor) / span) as f32 * 78.0).max(4.0);
        let mark = if line {
            col()
                .w_full()
                .h(h)
                .items_center()
                .child(
                    el().size(12.0, 12.0)
                        .radius(6.0)
                        .fill(c)
                        .border(3.0, c.alpha(0.3)),
                )
                .child(el().w(2.0).grow(1.0).fill(c.alpha(0.25)))
        } else {
            col()
                .w_full()
                .h(h)
                .radius(8.0)
                .linear_gradient(180.0, [(0.0, c), (1.0, c.alpha(0.35))])
        };
        bars = bars.child(
            col()
                .key(format!("{key}-bar-{i}"))
                .grow(1.0)
                .h_full()
                .justify_end()
                .items_center()
                .gap(4.0)
                .child(t(
                    format!("{v:.0}{unit}"),
                    TextStyle::new(11.0, 600.0),
                    TEXT,
                ))
                .child(mark)
                .child(t(
                    labels.get(i).cloned().unwrap_or_default(),
                    TextStyle::new(10.5, 500.0),
                    DIM,
                )),
        );
    }
    bars.key(format!("{key}-chart"))
}

/// One card of a document, drawn with what it carries.
pub fn card_view(c: &Value, key: &str, s: &State, compact: bool) -> El {
    let tone = tone_colour(c["tone"].as_str().unwrap_or(""));
    let mut body = col()
        .key(key)
        .w_full()
        .padding(if compact { 14.0 } else { 16.0 })
        .gap(10.0)
        .radius(22.0)
        .fill(SURFACE)
        .border(1.0, HAIRLINE);

    // a photo first, edge to edge
    if let Some(path) = c["image"].as_str().filter(|p| !p.is_empty()) {
        if let Some(px) = s.images.get(path) {
            let (w, h) = px.size();
            let ratio = if w > 0 { h as f32 / w as f32 } else { 0.75 };
            let shown_w = if compact { 140.0 } else { 318.0 };
            body = body.child(
                el().key(format!("{key}-image"))
                    .w_full()
                    .h(shown_w * ratio)
                    .radius(16.0)
                    .clip_rounded(16.0)
                    .pixels_fit(px, rune::SurfaceFit::Fill),
            );
        } else {
            body = body.child(
                row()
                    .w_full()
                    .h(if compact { 90.0 } else { 200.0 })
                    .center()
                    .radius(16.0)
                    .fill(SURFACE2)
                    .child(icon(&icons::CAMERA, 28.0).color(DIM)),
            );
        }
    }

    // the title, with the badge on the right
    let mut head = row().w_full().gap(8.0).center_y().child(
        t(
            str_of(&c["title"]),
            if compact { CALLOUT } else { HEADLINE },
            if compact { MUTED } else { TEXT },
        )
        .grow(1.0)
        .shrink()
        .truncate(),
    );
    let badge = str_of(&c["badge"]);
    if !badge.is_empty() && !compact {
        head = head.child(
            row()
                .h(24.0)
                .px(10.0)
                .center()
                .radius(12.0)
                .fill(tone.alpha(0.16))
                .child(t(badge, MICRO, tone)),
        );
    }
    body = body.child(head);
    let sub = str_of(&c["subtitle"]);
    if !sub.is_empty() {
        body = body.child(t(sub, CAPTION, MUTED).w_full().wrap());
    }

    // a big number, with its change in green or red
    if let Some(m) = c["metric"].as_object() {
        let value = m
            .get("value")
            .and_then(Value::as_str)
            .unwrap_or("")
            .to_string();
        let label = m
            .get("label")
            .and_then(Value::as_str)
            .unwrap_or("")
            .to_string();
        let delta = m
            .get("delta")
            .and_then(Value::as_str)
            .unwrap_or("")
            .to_string();
        let mut r = row().gap(8.0).items_end().child(t(
            value,
            TextStyle::new(if compact { 28.0 } else { 40.0 }, 700.0),
            TEXT,
        ));
        if !label.is_empty() {
            r = r.child(t(label, CAPTION, MUTED).pb(6.0));
        }
        body = body.child(r.key(format!("{key}-metric")));
        if !delta.is_empty() {
            let up = !delta.starts_with('-');
            body = body.child(
                row()
                    .h(24.0)
                    .px(10.0)
                    .center()
                    .radius(12.0)
                    .fill(if up { GOOD } else { BAD }.alpha(0.16))
                    .child(t(delta, MICRO, if up { GOOD } else { BAD })),
            );
        }
    }

    // a bar
    if let Some(p) = c["progress"].as_f64() {
        body = body.child(
            row()
                .key(format!("{key}-progress"))
                .w_full()
                .h(8.0)
                .radius(4.0)
                .fill(SURFACE3)
                .child(el().h_full().w_frac(p as f32).radius(4.0).fill(tone)),
        );
    }

    // a chart
    if !compact {
        if let Some(ch) = c.get("chart").filter(|v| v.is_object()) {
            body = body.child(chart(ch, tone, key));
        }
    }

    // lines
    let lines: Vec<String> = c["lines"]
        .as_array()
        .into_iter()
        .flatten()
        .map(str_of)
        .collect();
    for l in lines.iter().take(if compact { 2 } else { 8 }) {
        body = body.child(t(l.clone(), CAPTION, MUTED).w_full().wrap());
    }

    // buttons: each says its words back to the agent
    let actions = c["actions"].as_array().cloned().unwrap_or_default();
    if !actions.is_empty() {
        let mut r = row().w_full().gap(8.0).flex_wrap();
        for (i, b) in actions.iter().enumerate().take(if compact { 1 } else { 6 }) {
            let say = str_of(&b["say"]);
            r = r.child(
                pill(
                    &format!("{key}-do-{i}"),
                    &str_of(&b["label"]),
                    ACCENT.alpha(0.18),
                    ACCENT,
                )
                .on_press(move |s: &mut State| s.ask(&say)),
            );
        }
        body = body.child(r);
    }
    body
}

/// A whole document: its title and its cards, and buttons for the whole screen.
pub fn document(doc: &Value, key: &str, s: &State, with_actions: bool) -> El {
    let (ic, c) = kind_mark(doc["kind"].as_str().unwrap_or(""));
    let mut out = col().key(key).w_full().gap(10.0).child(
        row()
            .w_full()
            .gap(10.0)
            .center_y()
            .child(tile(ic, c, 30.0))
            .child(
                col()
                    .grow(1.0)
                    .shrink()
                    .min_w(0.0)
                    .child(t(str_of(&doc["title"]), HEADLINE, TEXT).truncate())
                    .child(t(str_of(&doc["subtitle"]), CAPTION, MUTED).truncate()),
            ),
    );
    for (i, card) in doc["cards"].as_array().into_iter().flatten().enumerate() {
        out = out.child(card_view(card, &format!("{key}-card-{i}"), s, false));
    }
    let actions = doc["actions"].as_array().cloned().unwrap_or_default();
    if !actions.is_empty() {
        let mut r = row().w_full().gap(8.0).flex_wrap();
        for (i, b) in actions.iter().enumerate() {
            let say = str_of(&b["say"]);
            r = r.child(
                pill(
                    &format!("{key}-act-{i}"),
                    &str_of(&b["label"]),
                    SURFACE2,
                    TEXT,
                )
                .on_press(move |s: &mut State| s.ask(&say)),
            );
        }
        out = out.child(r);
    }
    out
}

/// The dashboard: its cards as widgets, two to a row.
pub fn dashboard(doc: &Value, s: &State) -> El {
    let cards = doc["cards"].as_array().cloned().unwrap_or_default();
    let mut grid = col().key("dashboard").w_full().gap(10.0);
    for (r, pair) in cards.chunks(2).enumerate() {
        let mut line = row().w_full().gap(10.0).items_start();
        for (i, c) in pair.iter().enumerate() {
            line = line.child(
                card_view(c, &format!("widget-{}", r * 2 + i), s, true)
                    .grow(1.0)
                    .w_frac(0.5)
                    .min_w(0.0),
            );
        }
        if pair.len() == 1 {
            line = line.child(el().grow(1.0).w_frac(0.5));
        }
        grid = grid.child(line);
    }
    grid
}
